# --------------------------------------------------------------------------------------------------
# Institutions.  founded = year, never later than 1975; founded_basis is "assumption" where the codex
# gives no date.  owners / leaders are person keys.  price_key points into prices_1975.json.
# --------------------------------------------------------------------------------------------------
def I(key, name, category, place, founded, notes, band="MEDIUM", price_key=None, owners=(), leaders=(), basis="assumption",
      liquidity="STABLE_BASELINE", asset_base="MIXED"):
    return dict(key=key, name=name, category=category, place=place, founded=founded, founded_basis=basis, notes=notes,
                band=band, price_key=price_key, owners=list(owners), leaders=list(leaders), liquidity=liquidity,
                asset_base=asset_base)


