# --------------------------------------------------------------------------------------------------
# Persons.
#   P(key, name, sex, age_1975, age_1980, role, post_1975, post_1980, reason, institutions, location, public, current, ...)
#   age_1980 is None for people the codex gives no age (added men and women); they carry post_1980=None.
#   added = a code letter for a person who is not in the codex cast with an age (men and women added by me).
# --------------------------------------------------------------------------------------------------
def P(key, name, sex, age, age80, role, post75, post80, reason, insts, loc, public, current, tier="DORMANT", added=None):
    return dict(key=key, name=name, sex=sex, age=age, age80=age80, role=role, post75=post75, post80=post80, reason=reason,
                insts=list(insts), loc=loc, public=public, current=current, tier=tier, added=added)


